<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Add question · Northvale Admin</title><?php $adminSection='exams'; ?><?= $this->include('admin/_styles') ?></head><body><div class="admin-app"><?php $username=session()->get('admin_username');$usertype=session()->get('admin_usertype'); ?><?= $this->include('admin/_sidebar') ?><main class="admin-main"><header class="admin-topbar"><div class="admin-top-title">Add question</div><div class="admin-search">⌕ <span>Search...</span><span style="margin-left:auto">⌘ K</span></div><div class="admin-pill">✦ AI insights</div><div style="font-size:20px;color:#778092">☼</div></header><div class="admin-content"><div class="admin-heading"><div><h1>Add question to an exam</h1><p>Questions belong to an exam and appear when that exam is active.</p></div><a href="<?= site_url('admin/exams') ?>" style="color:#168fd4;font-size:13px">← Back to exams</a></div><div class="admin-card admin-form-card"><form method="post" enctype="multipart/form-data" action="<?= site_url('admin/questions') ?>"><?php if ($error): ?><div class="admin-error"><?= esc($error) ?></div><?php endif; ?><label for="exam_id">Exam</label><select id="exam_id" name="exam_id" required><option value="">Select an exam</option><?php foreach (($exams ?? []) as $exam): ?><option value="<?= esc($exam['id']) ?>" <?= ((int) ($data['exam_id'] ?? 0) === (int) $exam['id']) ? 'selected' : '' ?>><?= esc($exam['title']) ?></option><?php endforeach; ?></select><label for="type">Question type</label><select id="type" name="type"><option value="single">Single choice</option><option value="multi">Multiple choice</option><option value="bool">True / false</option><option value="written">Written answer</option><option value="upload">PDF upload</option></select><label for="prompt">Question prompt</label><textarea id="prompt" name="prompt" required><?= esc($data['prompt'] ?? '') ?></textarea><label for="hint">Hint / instructions</label><input id="hint" name="hint" value="<?= esc($data['hint'] ?? '') ?>"><label for="points">Points</label><input id="points" name="points" type="number" min="1" value="<?= esc($data['points'] ?? 1) ?>"><label for="options">Options</label><textarea id="options" name="options" placeholder="One option per line"></textarea><p style="font-size:13px;color:#798196">Required for choice-based questions; options are automatically labelled A, B, C, and so on.</p><label for="attachments">Question attachments</label><input id="attachments" name="attachments[]" type="file" multiple accept=".pdf,.doc,.docx,.png,.jpg,.jpeg"><p style="font-size:13px;color:#798196">Optional. Select multiple PDF, Word, PNG, or JPG files. Each file can be up to 10 MB.</p><button class="admin-btn" type="submit" style="margin-top:22px">Add question</button></form></div></div></main></div></body></html>
